gDF(){return"\u0930\u094b\u0915\u093e \u091c\u093e \u0930\u0939\u093e \u0939\u0948\u2026"},
gDD(){return"\u0930\u094b\u0915\u0928\u0947 \u092a\u0930 \u0916\u093e\u0924\u093e \u0914\u0930 \u092c\u091a\u093e \u0939\u0941\u0906 \u0921\u0947\u091f\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0939\u0947\u0917\u093e\u0964 \u092a\u0939\u0932\u0947 \u0939\u091f\u093e\u092f\u093e \u0917\u092f\u093e \u0921\u0947\u091f\u093e \u0935\u093e\u092a\u0938 \u0928\u0939\u0940\u0902 \u0906\u090f\u0917\u093e; \u0906\u092a \u092c\u093e\u0926 \u092e\u0947\u0902 \u091c\u093e\u0930\u0940 \u0930\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gDE(){return"\u0916\u093e\u0924\u093e \u0939\u091f\u093e\u0928\u093e \u0930\u094b\u0915 \u0926\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964 \u0906\u092a \u0907\u0938\u0947 \u092c\u093e\u0926 \u092e\u0947\u0902 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932 \u0938\u0947 \u091c\u093e\u0930\u0940 \u0930\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
