gDO(){return"\u041d\u0435 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0439\u0442\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u043e \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435 \u043f\u0440\u043e\u0446\u0435\u0441\u0441."},
gDQ(){return"\u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f\u2026"},
DP(a,b,c){return"\u0423\u0434\u0430\u043b\u0435\u043d\u043e \u0437\u0430\u043a\u0430\u0437\u043e\u0432: "+a+" \u0438\u0437 "+b+". \u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c: "+c+"."},
gDL(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u043c \u043e\u0447\u0438\u0441\u0442\u043a\u0443\u2026"},
gDK(){return"\u0423\u0434\u0430\u043b\u044f\u0435\u043c \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u044b\u0435 \u0432\u0430\u043c\u0438 \u0437\u0430\u043a\u0430\u0437\u044b \u0438 \u043e\u0431\u0435\u0437\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u043c \u0432\u0430\u0448\u0435 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0447\u0443\u0436\u0438\u0445 \u0437\u0430\u043a\u0430\u0437\u0430\u0445\u2026"},
gDM(){return"\u041e\u0431\u0435\u0437\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u043c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u043c \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438 \u0437\u0430\u043a\u0430\u0437\u043e\u0432\u2026"},
gDG(){return"\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u043c \u043e\u0431\u0449\u0438\u0435 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0438 \u0432 \u0440\u0435\u0436\u0438\u043c \u0447\u0442\u0435\u043d\u0438\u044f \u0438 \u0443\u0434\u0430\u043b\u044f\u0435\u043c \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u0432\u0430\u0441\u2026"},
gDJ(){return"\u041e\u0431\u0435\u0437\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u043c \u043e\u0431\u0449\u0438\u0435 \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u0438 \u0443\u0434\u0430\u043b\u044f\u0435\u043c \u043b\u0438\u0447\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438\u2026"},
gDN(){return"\u0423\u0434\u0430\u043b\u044f\u0435\u043c \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u044b\u0435 \u0441\u0432\u044f\u0437\u0438 \u0441 \u0437\u0430\u043a\u0430\u0437\u0430\u043c\u0438\u2026"},
